// จัดกลุ่มรายการห้อง (จาก API) ให้เป็น section ตามชั้น
// รองรับกรณีห้องแต่ละรายการมี field "floor" ติดมาด้วย
function groupRoomsByFloor(rooms) {
  const grouped = {};

  rooms.forEach(function (room) {
    const floor = room.floor || 1;
    if (!grouped[floor]) grouped[floor] = [];
    grouped[floor].push(room);
  });

  return Object.keys(grouped)
    .sort(function (a, b) {
      return Number(a) - Number(b);
    })
    .map(function (floor) {
      return {
        floor: Number(floor),
        rooms: grouped[floor]
      };
    });
}

function escapeHtml(str) {
  return String(str)
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;");
}

function renderFloorSections(floorSections) {

  const container = document.getElementById("floorSections");
  container.innerHTML = "";

  floorSections.forEach(function (section) {

    const floorDiv = document.createElement("div");
    floorDiv.className = "floor-container";

    const floorTab = document.createElement("div");
    floorTab.className = "floor-tab";
    floorTab.textContent = "ชั้น " + section.floor;
    floorDiv.appendChild(floorTab);

    const roomsDiv = document.createElement("div");
    roomsDiv.className = "floor-rooms";

    section.rooms.forEach(function (room) {

      const card = document.createElement("div");
      card.className = "room-card-dark";

      const descHtml = room.description
        ? '<p class="room-desc">' +
          room.description
            .split("\n")
            .map(function (line) {
              return "<span>" + escapeHtml(line) + "<br /></span>";
            })
            .join("") +
          "</p>"
        : "";

      card.innerHTML =
        '<div class="room-image">รูปห้อง</div>' +
        '<div class="room-info">' +
          '<div class="room-header">' +
            "<h2>" + escapeHtml(room.room_name || "ชื่อห้อง") + "</h2>" +
            '<span class="capacity-badge">' + escapeHtml(room.capacity_label || "ความจุ:") + "</span>" +
          "</div>" +
          descHtml +
          '<div class="time-slot">' +
            '<div class="time-bar"></div>' +
            '<div class="time-row">' +
              "<span>9:00</span><span>10:00</span><span>11:00</span><span>12:00</span>" +
              "<span>13:00</span><span>14:00</span><span>15:00</span><span>16:00</span>" +
            "</div>" +
          "</div>" +
        "</div>";

      roomsDiv.appendChild(card);

    });

    floorDiv.appendChild(roomsDiv);
    container.appendChild(floorDiv);

  });

}

document.addEventListener("DOMContentLoaded", function () {

  const userData = localStorage.getItem("user");

  if (!userData) {
    window.location.href = "index.html";
    return;
  }

  const user = JSON.parse(userData);

  // เติมข้อมูลใน popup โปรไฟล์
  document.getElementById("pf-name").textContent = user.displayname_th || "";
  document.getElementById("pf-username").textContent = user.username || "";
  document.getElementById("pf-faculty").textContent = user.faculty || "";
  document.getElementById("pf-department").textContent = user.department || "";
  document.getElementById("pf-email").textContent = user.email || "";

  // toggle profile popup
  const profileBtn = document.getElementById("profileBtn");
  const profilePopup = document.getElementById("profilePopup");
  const closeProfileBtn = document.getElementById("closeProfileBtn");
  const logoutBtn = document.getElementById("logoutBtn");

  profileBtn.addEventListener("click", function () {
    profilePopup.hidden = !profilePopup.hidden;
  });

  closeProfileBtn.addEventListener("click", function () {
    profilePopup.hidden = true;
  });

  logoutBtn.addEventListener("click", function () {
    localStorage.removeItem("token");
    localStorage.removeItem("user");
    window.location.href = "index.html";
  });

  // ดึงข้อมูลห้อง (ถ้ามีจริงจาก API ใช้ข้อมูลจริง ถ้าไม่มีใช้ข้อมูลตัวอย่าง)
  fetch("http://localhost:5001/api/rooms")
    .then(function (response) {
      return response.json();
    })
    .then(function (data) {
      const bookings = data.rooms || [];
      const floorSections =
        bookings.length > 0 ? groupRoomsByFloor(bookings) : MOCK_ROOMS_BY_FLOOR;
      renderFloorSections(floorSections);
    })
    .catch(function (error) {
      console.log(error);
      renderFloorSections(MOCK_ROOMS_BY_FLOOR);
    });

});
